BEGIN
 IF current_database()<>'club_arena_qualification' OR inet_server_addr() IS NOT NULL
 OR current_user<>'supabase_admin' OR session_user<>'supabase_admin'
 OR NOT EXISTS(SELECT FROM pg_roles WHERE oid=10 AND rolname=current_user AND rolsuper)
 THEN RAISE EXCEPTION 'FIXTURE_ORIGINAL_BOOTSTRAP_REQUIRED'; END IF;
 WITH RECURSIVE seed AS (SELECT oid FROM pg_roles WHERE rolname=ANY(ARRAY['anon','authenticated','authenticator','cli_login_postgres','dashboard_user','pgbouncer','postgres','service_role','supabase_admin','supabase_auth_admin','supabase_backup_admin','supabase_etl_admin','supabase_functions_admin','supabase_privileged_role','supabase_read_only_user','supabase_realtime_admin','supabase_replication_admin','supabase_storage_admin'])),
 reachable(oid) AS (SELECT oid FROM seed UNION SELECT CASE WHEN m.member=r.oid THEN m.roleid ELSE m.member END FROM pg_auth_members m JOIN reachable r ON m.member=r.oid OR m.roleid=r.oid),
 scoped_roles AS (SELECT * FROM pg_roles WHERE oid IN(SELECT oid FROM reachable))
 SELECT jsonb_build_object(
 'roles',(SELECT jsonb_agg(jsonb_build_object('name',rolname,'superuser',rolsuper,'inherit',rolinherit,'create_role',rolcreaterole,'create_db',rolcreatedb,'login',rolcanlogin,'replication',rolreplication,'bypass_rls',rolbypassrls,'connection_limit',rolconnlimit,'valid_until',rolvaliduntil::text,'configuration',(SELECT jsonb_agg(jsonb_build_object('key',split_part(c,'=',1),'value',CASE WHEN split_part(c,'=',1)=ANY(ARRAY['search_path','log_statement','statement_timeout','session_preload_libraries','lock_timeout','idle_in_transaction_session_timeout','pgrst.db_pre_request','default_transaction_read_only']) THEN substr(c,strpos(c,'=')+1) END,'value_md5',md5(substr(c,strpos(c,'=')+1))) ORDER BY split_part(c,'=',1)) FROM unnest(rolconfig) c)) ORDER BY rolname) FROM scoped_roles),
 'memberships',(SELECT jsonb_agg(jsonb_build_object('role',pg_get_userbyid(m.roleid),'member',pg_get_userbyid(m.member),'grantor',pg_get_userbyid(m.grantor),'admin',m.admin_option,'inherit',m.inherit_option,'set',m.set_option) ORDER BY pg_get_userbyid(m.roleid),pg_get_userbyid(m.member),pg_get_userbyid(m.grantor)) FROM pg_auth_members m WHERE m.roleid IN(SELECT oid FROM reachable) OR m.member IN(SELECT oid FROM reachable)),
 'role_settings',(SELECT jsonb_agg(v ORDER BY v->>'role',v->>'database') FROM (SELECT jsonb_build_object('role',CASE WHEN s.setrole=0 THEN 'ALL' ELSE pg_get_userbyid(s.setrole) END,'database',CASE WHEN s.setdatabase=0 THEN 'ALL' WHEN s.setdatabase=(SELECT oid FROM pg_database WHERE datname=current_database()) THEN 'OWNED_DATABASE' ELSE (SELECT datname FROM pg_database WHERE oid=s.setdatabase) END,'settings',(SELECT jsonb_agg(jsonb_build_object('key',split_part(c,'=',1),'value',CASE WHEN split_part(c,'=',1)=ANY(ARRAY['search_path','log_statement','statement_timeout','session_preload_libraries','lock_timeout','idle_in_transaction_session_timeout','pgrst.db_pre_request','default_transaction_read_only']) THEN substr(c,strpos(c,'=')+1) END,'value_md5',md5(substr(c,strpos(c,'=')+1))) ORDER BY split_part(c,'=',1)) FROM unnest(s.setconfig) c)) v FROM pg_db_role_setting s WHERE s.setrole IN(SELECT oid FROM reachable) OR s.setrole=0) q),
 'default_acl',(SELECT jsonb_agg(v ORDER BY v->>'creator',v->>'schema',v->>'type') FROM (SELECT jsonb_build_object('creator',pg_get_userbyid(d.defaclrole),'schema',CASE WHEN d.defaclnamespace=0 THEN 'GLOBAL' ELSE (SELECT nspname FROM pg_namespace WHERE oid=d.defaclnamespace) END,'type',d.defaclobjtype,'acl',(SELECT jsonb_agg(jsonb_build_object('grantor',pg_get_userbyid(a.grantor),'grantee',CASE WHEN a.grantee=0 THEN 'PUBLIC' ELSE pg_get_userbyid(a.grantee) END,'privilege',a.privilege_type,'grant_option',a.is_grantable) ORDER BY pg_get_userbyid(a.grantor),CASE WHEN a.grantee=0 THEN 'PUBLIC' ELSE pg_get_userbyid(a.grantee) END,a.privilege_type,a.is_grantable) FROM aclexplode(d.defaclacl) a)) v FROM pg_default_acl d WHERE d.defaclrole IN(SELECT oid FROM reachable)) q)
 ) INTO actual;
 IF actual IS DISTINCT FROM expected THEN
  SELECT jsonb_agg(k ORDER BY k) INTO differences FROM jsonb_object_keys(expected) k WHERE actual->k IS DISTINCT FROM expected->k;
  RAISE EXCEPTION 'FIXTURE_ROLE_GRAPH_POSTIMAGE_REQUIRED' USING DETAIL=differences::text;
 END IF;
END $role_graph$;
ROLLBACK;
